import { useEffect, useRef, useState, type ImgHTMLAttributes } from "react";
import type { NativeAtlasSource } from "./native-atlas";
import { IMAGE_LOAD_TIMEOUT_MS } from "./image-load-policy";

type Props = ImgHTMLAttributes<HTMLImageElement> & { atlas?: NativeAtlasSource | undefined; onResourceFailure?: (() => void) | undefined };
const identities = new WeakMap<NativeAtlasSource, number>();
let nextIdentity = 0;
/** Non-stage consumers retain IMG layout and share fallback ownership. */
export function DeferredAtlasImage({ atlas, onResourceFailure, ...props }: Props) {
  if (!atlas?.acquireFallback) return <img {...props} />;
  if (!identities.has(atlas)) identities.set(atlas, ++nextIdentity);
  return <DeferredImage key={`${identities.get(atlas)}:${props.src}`} atlas={atlas} onResourceFailure={onResourceFailure} {...props} />;
}
function DeferredImage({ atlas, onResourceFailure, ...props }: Props) {
  const [url, setUrl] = useState<string>();
  const [error, setError] = useState(false), [ready, setReady] = useState(false), [attempt, setAttempt] = useState(0);
  const failure = useRef(onResourceFailure); failure.current = onResourceFailure;
  const events = useRef({ ready: () => {}, fail: () => {} });
  useEffect(() => {
    const controller = new AbortController(); let active = true, release: (() => void) | undefined;
    const free = () => { release?.(); release = undefined; };
    const fail = () => {
      if (!active) return;
      active = false; clearTimeout(timer); controller.abort(); free(); setError(true); setUrl(undefined); failure.current?.();
    };
    const timer = setTimeout(fail, IMAGE_LOAD_TIMEOUT_MS);
    events.current = { fail, ready: () => { if (active) { clearTimeout(timer); setReady(true); } } };
    void atlas!.acquireFallback!(controller.signal).then(lease => {
      if (!active) { lease.release(); return; }
      release = lease.release; setUrl(lease.url);
    }).catch(fail);
    return () => { active = false; clearTimeout(timer); controller.abort(); free(); };
  }, [atlas, attempt]);
  if (error) return <span role="status">图片暂未加载成功。{onResourceFailure === undefined && <button type="button" onClick={event => { event.stopPropagation(); setError(false); setReady(false); setAttempt(value => value + 1); }}>重试图片</button>}</span>;
  return <img {...props} src={url} aria-busy={!ready} onLoad={event => { events.current.ready(); props.onLoad?.(event); }} onError={event => { events.current.fail(); props.onError?.(event); }} />;
}

sources.apps/player-shell/src/NativeAtlasImage.t:
import { useCallback, useEffect, useRef, useState, type ImgHTMLAttributes, type CanvasHTMLAttributes } from "react";
import { releaseAnimationsOnDetach } from "./owned-animations";
import { acquireNativeAtlasImage, acquireOrdinaryCanvasImage, nativeAtlasDiagnostics, type NativeAtlasSource } from "./native-atlas";
import { IMAGE_LOAD_TIMEOUT_MS } from "./image-load-policy";
import { ImageResourceBudgetError } from "./image-resource-policy";

const identities = new WeakMap<NativeAtlasSource["group"], number>();
let nextIdentity = 0;
function identity(atlas: NativeAtlasSource) {
  if (!identities.has(atlas.group)) identities.set(atlas.group, ++nextIdentity);
  return `${identities.get(atlas.group)}:${atlas.assetId}`;
}

export function NativeAtlasImage({ atlas, canvasSampling, onResourceFailure, onResourceState, hideResourceError, motionOwner, ...props }: ImgHTMLAttributes<HTMLImageElement> & { atlas?: NativeAtlasSource | undefined; canvasSampling?: boolean | undefined; hideResourceError?: boolean | undefined; motionOwner?: boolean | undefined; onResourceFailure?: (() => void) | undefined; onResourceState?: ((state: "loading" | "ready" | "error" | "timeout" | "budget" | "released") => void) | undefined }) {
  return atlas || canvasSampling ? <AtlasCanvas key={`${atlas ? identity(atlas) : "ordinary"}:${props.src}`} atlas={atlas} motionOwner={motionOwner} hideResourceError={hideResourceError} onResourceFailure={onResourceFailure} onResourceState={onResourceState} imageProps={props} /> : <img {...props} ref={motionOwner ? releaseAnimationsOnDetach : undefined} />;
}
function AtlasCanvas({ atlas, imageProps, onResourceFailure, onResourceState, hideResourceError, motionOwner }: { atlas: NativeAtlasSource | undefined; imageProps: ImgHTMLAttributes<HTMLImageElement>; motionOwner: boolean | undefined; hideResourceError: boolean | undefined; onResourceFailure: (() => void) | undefined; onResourceState: ((state: "loading" | "ready" | "error" | "timeout" | "budget" | "released") => void) | undefined }) {
  const report=useRef(onResourceState);report.current=onResourceState;
  const ref = useRef<HTMLCanvasElement>(null), [failed, setFailed] = useState(false);
  const ownCanvas = useCallback((element: HTMLCanvasElement | null) => { ref.current = element; if (element && motionOwner) return releaseAnimationsOnDetach(element); }, [motionOwner]);
  const [resourceError, setResourceError] = useState<"failed" | "timeout" | "budget" | null>(null), [attempt, setAttempt] = useState(0);
  const [fallbackUrl, setFallbackUrl] = useState(imageProps.src ?? "");
  const [preparing, setPreparing] = useState(true);
  const failureCallback = useRef(onResourceFailure); failureCallback.current = onResourceFailure;
  const events = useRef({ ready: () => {}, fail: () => {} });
  useEffect(() => {
    let active = true, release: (() => void) | undefined, releaseFallback: (() => void) | undefined;
    const controller = new AbortController();
    const canvas = ref.current;
    if (!canvas) return;
    const free = () => { release?.(); release = undefined; releaseFallback?.(); releaseFallback = undefined; };
    const fail = (reason: "failed" | "timeout" | "budget") => {
      if (!active) return;
      active = false; clearTimeout(timer); controller.abort(); free();
      setPreparing(false); setResourceError(reason); report.current?.(reason === "failed" ? "error" : reason); failureCallback.current?.();
    };
    const timer = setTimeout(() => fail("timeout"), IMAGE_LOAD_TIMEOUT_MS);
    const ready = () => { if (active) { clearTimeout(timer); setPreparing(false); report.current?.("ready"); } };
    events.current = { ready, fail: () => fail("failed") };
    report.current?.("loading");
    const load=async()=>{
      let url=imageProps.src ?? "";
      if(atlas?.acquireFallback){
        try {
          const lease=await atlas.acquireFallback(controller.signal);
          if(!active){lease.release();controller.signal.throwIfAborted();}
          releaseFallback=lease.release;url=lease.url;setFallbackUrl(url);
        } catch(error){fail(error instanceof DOMException && error.name === "TimeoutError" ? "timeout" : "failed");throw error;}
      }
      if(atlas){try{return {image:await acquireNativeAtlasImage(atlas,canvas,controller.signal),mode:"ready"};}catch{controller.signal.throwIfAborted();}}
      return {image:await acquireOrdinaryCanvasImage(url,canvas,controller.signal),mode:atlas?"fallback":"ordinary"};
    };
    void load().then(({image,mode}) => {
      if (!active) { image.release(); return; }
      release = image.release; canvas.dataset.nativeAtlas = mode; canvas.dataset.canvasSampling = "ready";
      ready();
      canvas.dataset.nativeAtlasAccountedBytes = String(nativeAtlasDiagnostics().accountedBytes);
    }).catch(error => { if (!active)return;if(error instanceof ImageResourceBudgetError)fail("budget");else if(error instanceof DOMException&&error.name==="TimeoutError")fail("timeout");else setFailed(true); });
    return () => { active = false; clearTimeout(timer); controller.abort(); free(); report.current?.("released"); };
  }, [atlas?.group, atlas?.assetId, imageProps.src, attempt]);
  if (resourceError && hideResourceError) return null;
  if(resourceError)return <div role="alert" style={{position:"absolute",zIndex:20,inset:"30% 10% auto",padding:16,background:"#181827",color:"white"}}>{resourceError === "timeout" ? "画面加载超时，已停止自动推进。可以重试或手动继续。" : resourceError === "budget" ? "画面资源超过安全预算或仍在释放，已停止自动推进。可稍后重试或手动继续。" : "画面资源未能加载，请重试；若仍失败，请重新下载完整游戏。"}<button type="button" style={{minHeight:44,pointerEvents:"auto"}} onClick={event=>{event.stopPropagation();setResourceError(null);setFailed(false);setPreparing(true);setAttempt(value=>value+1);}}>重试画面资源</button></div>;
  if (failed) return <img {...imageProps} ref={motionOwner ? releaseAnimationsOnDetach : undefined} src={fallbackUrl} aria-busy={preparing} onLoad={event=>{events.current.ready();imageProps.onLoad?.(event);}} onError={event=>{events.current.fail();imageProps.onError?.(event);}} data-native-atlas={atlas?"fallback":"ordinary"} data-canvas-sampling="emergency-img" title="Canvas 暂不可用，已降级普通图片；缩放采样可能不同" />;
  const { src: _src, alt, onError: _onError, onLoad: _onLoad, ...rest } = imageProps;
  return <><canvas {...rest as unknown as CanvasHTMLAttributes<HTMLCanvasElement>} ref={ownCanvas} role="img" aria-label={alt} aria-busy={preparing} data-native-atlas="loading" />{preparing&&<span role="status" style={{position:"absolute",zIndex:20,top:12,left:12,background:"#181827",color:"white",padding:8,pointerEvents:"none"}}>正在准备画面资源…</span>}</>;
}

