import { useMemo, useRef, useState, type ReactNode } from 'react';
import type { PlayerCoreSnapshotV1, PlayerHistoryVisibleEventV1 } from '@world-studio/player-core';
import { PlayerHistoryPage } from './PlayerHistoryPage';
import { parsePlayerRichTextV1 } from './player-typography';

function eventLabel(event: PlayerHistoryVisibleEventV1): string {
  switch (event.kind) {
    case 'dialogue': case 'narration': return event.text;
    case 'choice': return event.prompt;
    case 'wait': return `等待 ${event.durationMilliseconds} 毫秒`;
    case 'ending': return event.name;
  }
}
function eventKind(event: PlayerHistoryVisibleEventV1): string {
  return { dialogue: '对白', narration: '旁白', choice: '选择', wait: '等待', ending: '结局' }[event.kind];
}
const normalize = (text: string) => text.normalize('NFKC').toLowerCase();
function searchText(event: PlayerHistoryVisibleEventV1): string {
  const parts = parsePlayerRichTextV1(eventLabel(event));
  return normalize(parts.map(part => part.kind === 'text' ? part.text : part.base).join('') + '\n' +
    parts.flatMap(part => part.kind === 'ruby' ? [part.annotation] : []).join(' '));
}

/** Search only the presentation snapshot. Core remains the navigation authority;
 * archived and future rows never gain a rollback action through filtering.
 */
export function PlayerHistoryContent({ history, locale, canNavigate, onNavigate, renderText }: {
  readonly history: NonNullable<PlayerCoreSnapshotV1['history']>;
  readonly locale: string;
  readonly canNavigate: boolean;
  readonly onNavigate: (entryId: string) => void;
  readonly renderText: (text: string) => ReactNode;
}) {
  const [query, setQuery] = useState(''), search = normalize(query.trim());
  const input = useRef<HTMLInputElement | null>(null);
  const indexed = useMemo(() => ({ active: history.activeEntries.map(entry => ({ entry, text: searchText(entry.event) })),
    archives: history.archives.map((archive, index) => ({ archive, index, rows: archive.entries.map(entry => ({ entry, text: searchText(entry.event) })) })) }), [history]);
  const active = indexed.active.filter(row => !search || row.text.includes(search)).map(row => row.entry);
  const archives = indexed.archives.map(item => ({ ...item, entries: item.rows.filter(row => !search || row.text.includes(search)).map(row => row.entry) }));
  const matches = active.length + archives.reduce((count, archive) => count + archive.entries.length, 0);
  return <>
    <div className="player-history-search">
      <label htmlFor="player-history-query">查找已记录的剧情</label>
      <div><input ref={input} id="player-history-query" type="search" value={query} placeholder="输入对白、旁白或结局中的文字" maxLength={256} onChange={event => setQuery(event.target.value)} onKeyDown={event => {
        if (event.key === 'Escape' && query && !event.nativeEvent.isComposing) { event.preventDefault(); event.stopPropagation(); setQuery(''); }
      }} />
        {query && <button type="button" onClick={() => { setQuery(''); input.current?.focus(); }}>清除查找</button>}</div>
      <p role="status">{search ? `找到 ${matches} 条记录` : '查找当前主线与只读归档；前方及归档记录不能回退。'}</p>
    </div>
    <div className="player-history-panel-body">
      {history.forwardPolicy.blocked && <p className="player-history-panel__notice" role="status">项目设置禁止在回退后沿原分支前进。</p>}
      {history.backwardBarrier !== null && <p className="player-history-panel__barrier" role="status"><strong>不可逆边界</strong><span>{history.backwardBarrier.reason}</span><small>距离当前位置 {history.backwardBarrier.distance} 步 · {history.backwardBarrier.descriptorId}</small></p>}
      {search && matches === 0 && <p className="player-history-panel__empty">没有找到匹配记录，试试更短的词句，或清除查找回到当前句。</p>}
      {(!search || active.length > 0) && <section className="player-history-panel__section">
        <h3>当前主线{search ? ` · ${active.length} 条` : ''}</h3>
        {active.length === 0 ? <p className="player-history-panel__empty">尚无可显示条目。</p> : <PlayerHistoryPage key={`active:${search}`} entries={active} currentEntryId={active.find(entry => entry.position === 'current')?.entryId} label="当前主线">{visible => <ol className="player-history-list">{visible.map(entry => {
          const label = eventLabel(entry.event);
          return <li key={entry.entryId} data-history-position={entry.position}>{entry.canNavigateBack ?
            <button type="button" aria-label={`回退到：${label}`} disabled={!canNavigate} onClick={() => onNavigate(entry.entryId)}><span>{eventKind(entry.event)} · {entry.position === 'past' ? '已读' : '当前'}</span><strong className="player-typography-text" lang={locale}>{renderText(label)}</strong></button> :
            <div><span>{eventKind(entry.event)} · {entry.position === 'future' ? '前方 · ' : ''}不可回退</span><strong className="player-typography-text" lang={locale}>{renderText(label)}</strong></div>}</li>;
        })}</ol>}</PlayerHistoryPage>}
      </section>}
      {archives.filter(item => !search || item.entries.length > 0).map(({ archive, index, entries }) => <section className="player-history-panel__section player-history-panel__archive" key={archive.archiveId} data-archive-id={archive.archiveId}>
        <h3>归档记录 {index + 1}{search ? ` · ${entries.length} 条` : ''}</h3><p>旧分支或内存保护归档 · 只读，不支持回滚</p>
        <PlayerHistoryPage key={`${archive.archiveId}:${search}`} entries={entries} label={`归档记录 ${index + 1}`}>{visible => <ol className="player-history-list">{visible.map(entry => <li key={entry.entryId}><div><span>{eventKind(entry.event)} · 归档</span><strong className="player-typography-text" lang={locale}>{renderText(eventLabel(entry.event))}</strong></div></li>)}</ol>}</PlayerHistoryPage>
      </section>)}
    </div>
  </>;
}

import { useEffect, useRef, useState, type ReactNode } from 'react';

const PAGE_SIZE = 40;

/** Bound the visible history without trimming the authoritative session. */
export function PlayerHistoryPage<T extends { readonly entryId: string }>({ entries, currentEntryId, label, children }: {
  readonly entries: readonly T[];
  readonly currentEntryId?: string | undefined;
  readonly label: string;
  readonly children: (visible: readonly T[]) => ReactNode;
}) {
  const lastPage = Math.max(0, Math.ceil(entries.length / PAGE_SIZE) - 1);
  const anchor = currentEntryId === undefined ? -1 : entries.findIndex(entry => entry.entryId === currentEntryId);
  const currentPage = anchor < 0 ? lastPage : Math.floor(anchor / PAGE_SIZE);
  const [selectedPage, setSelectedPage] = useState(currentPage);
  const [scrollRequest, setScrollRequest] = useState(0);
  const moveTo = (next: number) => { setSelectedPage(next); setScrollRequest(value => value + 1); };
  const page = Math.min(selectedPage, lastPage), start = page * PAGE_SIZE;
  const records = useRef<HTMLDivElement | null>(null);
  useEffect(() => {
    // Readonly archives must not steal the initial scroll from the active line.
    if (currentEntryId === undefined && scrollRequest === 0) return;
    const target = page === currentPage
      ? records.current?.querySelector('[data-history-position="current"]') ?? records.current?.querySelector('li:last-child')
      : records.current?.querySelector('li');
    target?.scrollIntoView?.({ block: page === currentPage ? 'nearest' : 'start' });
  }, [page, currentPage, currentEntryId, entries.length, scrollRequest]);
  return <>
    {lastPage > 0 && <nav className="player-history-pages" aria-label={`${label}分页`}>
      <span role="status">第 {start + 1}–{Math.min(start + PAGE_SIZE, entries.length)} 条，共 {entries.length} 条</span>
      <div>
        <button type="button" aria-label={`${label}：较早记录`} disabled={page === 0} onClick={() => moveTo(page - 1)}>← 较早</button>
        <button type="button" aria-label={currentEntryId === undefined ? '最新记录' : '定位当前记录'} onClick={() => moveTo(currentPage)}>{currentEntryId === undefined ? '最新' : '当前句'}</button>
        <button type="button" aria-label={`${label}：较后记录`} disabled={page === lastPage} onClick={() => moveTo(page + 1)}>较后 →</button>
      </div>
    </nav>}
    <div ref={records} className="player-history-page-records">{children(entries.slice(start, start + PAGE_SIZE))}</div>
  </>;
}

