import { useEffect, useMemo, useState, type ComponentProps } from "react";
import { flushSync } from "react-dom";
import { PlayerShell, type PlayerHostActivityV1 } from "./PlayerShell";
import { IndexedDbWorldPlayerSaveStoreV3 } from "./player-save-store";
import { IndexedDbWorldPlayerRecoveryStoreV1 } from "./player-recovery-store";
import { createAppearancePreviewSaveStore } from "./appearance-preview-store";

export interface WebPlayerHostProps extends Omit<ComponentProps<typeof PlayerShell>, "hostActivity" | "platform"> {
  readonly activityOverride?: PlayerHostActivityV1;
}

function documentActivity(): PlayerHostActivityV1 {
  return typeof document !== "undefined" && document.visibilityState === "hidden" ? "suspended" : "active";
}

export function WebPlayerHost({ activityOverride, saveStore, recoveryStore, ...props }: WebPlayerHostProps) {
  const [activity, setActivity] = useState(documentActivity);
  const [frozen, setFrozen] = useState(false);
  const [pageHidden, setPageHidden] = useState(false);
  const resolvedSaveStore = useMemo(() => props.editorPreview ? createAppearancePreviewSaveStore() : saveStore ?? (typeof indexedDB === "undefined" ? undefined : new IndexedDbWorldPlayerSaveStoreV3(indexedDB)), [saveStore, props.editorPreview]);
  const resolvedRecoveryStore = useMemo(() => props.editorPreview ? undefined : recoveryStore ?? (typeof indexedDB === "undefined" ? undefined : new IndexedDbWorldPlayerRecoveryStoreV1(indexedDB)), [recoveryStore, props.editorPreview]);

  useEffect(() => {
    const onVisibilityChange = () => flushSync(() => setActivity(documentActivity()));
    // Commit timer/media suspension before the browser freezes the task queue.
    const onFreeze = () => flushSync(() => setFrozen(true));
    const onResume = () => flushSync(() => { setActivity(documentActivity()); setFrozen(false); });
    // pagehide/pageshow cover history-cache navigation in engines without the
    // freeze/resume API. Keep the ceilings independent: one event must not
    // accidentally resume a page still suspended for another reason.
    const onPageHide = () => flushSync(() => setPageHidden(true));
    const onPageShow = () => flushSync(() => { setActivity(documentActivity()); setPageHidden(false); });
    document.addEventListener("visibilitychange", onVisibilityChange);
    document.addEventListener("freeze", onFreeze);
    document.addEventListener("resume", onResume);
    window.addEventListener("pagehide", onPageHide);
    window.addEventListener("pageshow", onPageShow);
    return () => {
      document.removeEventListener("visibilitychange", onVisibilityChange);
      document.removeEventListener("freeze", onFreeze);
      document.removeEventListener("resume", onResume);
      window.removeEventListener("pagehide", onPageHide);
      window.removeEventListener("pageshow", onPageShow);
    };
  }, []);

  // Host permission may suspend playback, but must never override a hidden page.
  const effectiveActivity = frozen || pageHidden || activity === "suspended" || activityOverride === "suspended" ? "suspended" : "active";
  return <PlayerShell {...props} {...(resolvedSaveStore === undefined ? {} : { saveStore: resolvedSaveStore })} {...(resolvedRecoveryStore === undefined ? {} : { recoveryStore: resolvedRecoveryStore })} platform="web" hostActivity={effectiveActivity} />;
}

sources.apps/player-shell/src/player-input.ts:
export interface PlayerGamepadFrameV1 {
  readonly buttons: readonly boolean[];
  readonly axes: readonly number[];
}

export type PlayerGamepadActionV1 = "primary" | "cancel" | "previous-choice" | "next-choice";

function pressed(frame: PlayerGamepadFrameV1, index: number): boolean {
  return frame.buttons[index] === true;
}

function rising(previous: PlayerGamepadFrameV1, current: PlayerGamepadFrameV1, index: number): boolean {
  return pressed(current, index) && !pressed(previous, index);
}

export function createEmptyPlayerGamepadFrameV1(): PlayerGamepadFrameV1 {
  return { buttons: [], axes: [] };
}

export function playerGamepadActionV1(previous: PlayerGamepadFrameV1, current: PlayerGamepadFrameV1): PlayerGamepadActionV1 | null {
  const previousY = previous.axes[1] ?? 0;
  const currentY = current.axes[1] ?? 0;
  if (rising(previous, current, 12) || (currentY < -0.65 && previousY >= -0.65)) return "previous-choice";
  if (rising(previous, current, 13) || (currentY > 0.65 && previousY <= 0.65)) return "next-choice";
  if (rising(previous, current, 0)) return "primary";
  if (rising(previous, current, 1)) return "cancel";
  return null;
}

export function browserGamepadFrameV1(gamepad: Gamepad): PlayerGamepadFrameV1 {
  return {
    buttons: gamepad.buttons.map((button) => button.pressed),
    axes: [...gamepad.axes]
  };
}

/** One edge history per active polling session. New/reconnected devices must release
 * mapped controls before they can advance the story; held controls never repeat.
 */
export function createPlayerGamepadTrackerV1() {
  let device: string | null = null;
  let previous = createEmptyPlayerGamepadFrameV1();
  let armed = false;
  return (sample: { device: string; frame: PlayerGamepadFrameV1 } | null): PlayerGamepadActionV1 | null => {
    if (sample === null) {
      device = null;
      armed = false;
      previous = createEmptyPlayerGamepadFrameV1();
      return null;
    }
    const neutral = ![0, 1, 12, 13].some(index => pressed(sample.frame, index)) && Math.abs(sample.frame.axes[1] ?? 0) <= 0.65;
    if (device !== sample.device) {
      device = sample.device;
      previous = sample.frame;
      armed = neutral;
      return null;
    }
    if (!armed) {
      previous = sample.frame;
      armed = neutral;
      return null;
    }
    const action = playerGamepadActionV1(previous, sample.frame);
    previous = sample.frame;
    return action;
  };
}

