.player-history-search :is(input, button):focus-visible { outline: 3px solid var(--player-accent, #b9a1ff); outline-offset: 2px; }
.player-history-search p { margin: 8px 0 0; color: var(--player-muted, #c1bed2); font-size: 12px; line-height: 1.5; }
.player-history-panel-body { min-height: 0; overflow: auto; overscroll-behavior: contain; display: grid; align-content: start; gap: 14px; }
.player-history-page-records li { scroll-margin-block: 120px 8px; }
.player-background-save-notice { position: fixed; z-index: 36; top: calc(max(76px, env(safe-area-inset-top)) + var(--player-viewport-offset, 0px)); left: max(14px, env(safe-area-inset-left)); width: min(520px, calc(100vw - 28px)); box-sizing: border-box; padding: 16px; border: 1px solid var(--player-accent, #c5afff); border-radius: 16px; color: var(--player-ink, #f8f7ff); background: var(--player-panel, #111425); box-shadow: 0 10px 32px #0004; }
