.player-background-save-notice p { margin: 8px 0 12px; font-size: 13px; line-height: 1.6; overflow-wrap: anywhere; }
.player-background-save-notice__actions { display: flex; flex-wrap: wrap; gap: 8px; }
.player-background-save-notice button { min-height: 44px; padding: 8px 14px; border: 1px solid currentColor; border-radius: 10px; color: inherit; background: transparent; cursor: pointer; }
.player-background-save-notice button:first-child { background: var(--player-accent, #c5afff); color: var(--player-panel, #111425); border-color: transparent; }
.player-background-save-notice button:disabled { opacity: .5; cursor: not-allowed; }
.player-background-save-notice button:focus-visible { outline: 3px solid var(--player-accent, #c5afff); outline-offset: 3px; }
.player-history-pages { position: sticky; top: 0; z-index: 1; display: grid; gap: 8px; padding: 12px 0; background: var(--player-panel, #111425); color: var(--player-ink, #f8f7ff); }
