.player-history-pages button:disabled { opacity: .5; cursor: default; }
.player-history-pages button:focus-visible { outline: 3px solid var(--player-accent, #b9a1ff); outline-offset: 2px; }
.player-compact-toolbar button, .player-reading-menu-heading button {
  min-height: 44px; padding: 8px 14px; border: 1px solid var(--player-muted, #77758b);
  border-radius: 12px; background: var(--player-panel, #111425); color: var(--player-ink, #f8f7ff); cursor: pointer;
}
.player-compact-toolbar button:disabled { opacity: .45; cursor: not-allowed; }
.player-compact-toolbar .player-artwork-trigger { display: inline-flex; align-items: center; gap: 6px; }
.player-control-layer:not([data-open="true"]) .player-menu-only { display: none; }
.player-reading-menu-heading { display: grid; gap: 8px; padding-bottom: 16px; border-bottom: 1px solid var(--player-muted, #77758b); }
.player-reading-menu-heading strong { font-size: 22px; }
.player-reading-menu-heading span { color: var(--player-muted, #c1bed2); font-size: 13px; line-height: 1.6; }
.player-reading-menu-heading button { justify-self: end; }
