  .player-save__panel { padding: 12px; gap: 8px; }
  .player-save__panel > header { display: flex; flex-wrap: nowrap; align-items: center; gap: 10px; top: -12px; padding: 0; }
  .player-save__panel > header [data-save-message]:not([role="alert"]), .player-save__panel > .player-save-intro { display: none; }
