import { listWorldPlayerSaveSummariesV3, type WorldPlayerSaveSummaryV3, type WorldPlayerSaveStoreV3 } from "./player-save-store";
import type { WorldPlayerRecoveryRecordV1, WorldPlayerRecoveryStoreV1 } from "./player-recovery-store";

export const WORLD_PLAYER_AUTO_SAVE_SLOT_COUNT = 5;
export const WORLD_PLAYER_QUICK_SAVE_SLOT_ID = "quick-1" as const;
export const WORLD_PLAYER_CHECKPOINT_SAVE_SLOT_COUNT = 3;

export type WorldPlayerSaveWriteV1 = () => Promise<void>;
export type WorldPlayerAutoSaveResultV1 =
  | { readonly status: "written"; readonly slotId: string }
  | { readonly status: "coalesced"; readonly slotId: string };
export type WorldPlayerCheckpointSaveResultV1 =
  | { readonly status: "written"; readonly slotId: string }
  | { readonly status: "coalesced"; readonly slotId: string };

export function worldPlayerSaveSceneIdentityV1(buildId: string, sceneId: string): string {
  return `${buildId}\0${sceneId}`;
}

export function worldPlayerAutoSaveAllowedV1(status: string, presentationKind: string): boolean {
  return status === "presenting" && (presentationKind === "dialogue" || presentationKind === "narration") ||
    status === "waiting-choice" && presentationKind === "choice" || status === "ended" && presentationKind === "ending";
}

export class WorldPlayerSaveWriteCoordinatorV1 {
  private tail: Promise<void> = Promise.resolve();

  constructor(private readonly store: WorldPlayerSaveStoreV3) {}

  writeSerial(task: WorldPlayerSaveWriteV1): Promise<void> {
    const current = this.tail.then(task, task);
    this.tail = current.then(() => undefined, () => undefined);
    return current;
  }

  writeFixed<T>(task: () => Promise<T>): Promise<T> {
    return this.enqueue(task);
  }

  writeAuto(projectId: string, sceneIdentity: string, createAndWrite: (slotId: string) => Promise<void>): Promise<WorldPlayerAutoSaveResultV1> {
    return this.enqueue(async () => {
      const autoSlots = (await listWorldPlayerSaveSummariesV3(this.store, projectId)).filter((slot) => slot.kind === "auto");
      const newest = [...autoSlots].sort(newestFirst)[0];
      if (newest !== undefined && worldPlayerSaveSceneIdentityV1(newest.buildId, newest.sceneId) === sceneIdentity) {
        // A display header alone must not suppress a durable save. Only verify
        // the candidate being reused, not every unrelated slot in the catalog.
        const verified = this.store.listSummaries === undefined ? newest : await this.store.read(projectId, newest.slotId);
        if (verified !== null && worldPlayerSaveSceneIdentityV1(verified.buildId, verified.sceneId) === sceneIdentity) return { status: "coalesced" as const, slotId: newest.slotId };
      }
      const empty = Array.from({ length: WORLD_PLAYER_AUTO_SAVE_SLOT_COUNT }, (_, index) => `auto-${index + 1}`).find((slotId) => !autoSlots.some((slot) => slot.slotId === slotId));
      const slotId = empty ?? [...autoSlots].sort(oldestFirst)[0]?.slotId ?? "auto-1";
      await createAndWrite(slotId);
      return { status: "written" as const, slotId };
    });
  }

  writeCheckpoint(projectId: string, buildId: string, stepId: string, createAndWrite: (slotId: string) => Promise<void>): Promise<WorldPlayerCheckpointSaveResultV1> {
    return this.enqueue(async () => {
      const checkpointSlots = (await listWorldPlayerSaveSummariesV3(this.store, projectId)).filter((slot) => slot.kind === "checkpoint");
      const existing = [...checkpointSlots].sort(newestFirst).find((slot) => slot.buildId === buildId && slot.checkpointStepId === stepId);
      if (existing !== undefined) {
        await createAndWrite(existing.slotId);
        return { status: "coalesced" as const, slotId: existing.slotId };
      }
      const empty = Array.from({ length: WORLD_PLAYER_CHECKPOINT_SAVE_SLOT_COUNT }, (_, index) => `checkpoint-${index + 1}`).find((slotId) => !checkpointSlots.some((slot) => slot.slotId === slotId));
      const slotId = empty ?? [...checkpointSlots].sort(oldestFirst)[0]?.slotId ?? "checkpoint-1";
      await createAndWrite(slotId);
      return { status: "written" as const, slotId };
    });
  }

  private enqueue<T>(task: () => Promise<T>): Promise<T> {
    const current = this.tail.then(task, task);
    this.tail = current.then(() => undefined, () => undefined);
    return current;
  }
}

export class WorldPlayerRecoveryWriteCoordinatorV1 {
  private tail: Promise<void> = Promise.resolve();

  constructor(private readonly store: WorldPlayerRecoveryStoreV1) {}

  write(record: WorldPlayerRecoveryRecordV1): Promise<void> {
    return this.enqueue(() => this.store.write(record));
  }

  clear(projectId: string): Promise<void> {
    return this.enqueue(() => this.store.clear(projectId));
  }

  private enqueue(task: () => Promise<void>): Promise<void> {
    const current = this.tail.then(task, task);
    this.tail = current.then(() => undefined, () => undefined);
    return current;
  }
}

function oldestFirst(left: WorldPlayerSaveSummaryV3, right: WorldPlayerSaveSummaryV3): number {
  return left.savedAtEpochMilliseconds - right.savedAtEpochMilliseconds || left.slotId.localeCompare(right.slotId);
}

function newestFirst(left: WorldPlayerSaveSummaryV3, right: WorldPlayerSaveSummaryV3): number {
  return right.savedAtEpochMilliseconds - left.savedAtEpochMilliseconds || right.slotId.localeCompare(left.slotId);
}

import { packPlayerStorageRecord, unpackPlayerStorageRecord, readPlayerStorageMetadata, PlayerStorageWriteQueue } from "./player-storage-packing";
import { canonicalPlayerDataStringifyV1 } from "@world-studio/player-core";

export const WORLD_PLAYER_SAVE_STORE_VERSION = "3.0.0" as const;
export const WORLD_PLAYER_SAVE_DATABASE_NAME = "world-player-saves";
export const WORLD_PLAYER_SAVE_DATABASE_VERSION = 4;
export const WORLD_PLAYER_SAVE_STORE_NAME = "save-slots";
export const WORLD_PLAYER_SAVE_PREVIEW_STORE_NAME = "save-previews";
export const WORLD_PLAYER_RECOVERY_STORE_NAME = "recovery-sessions";
export const WORLD_PLAYER_SAVE_PREVIEW_MAXIMUM_BYTES = 512 * 1024;
export const WORLD_PLAYER_SAVE_PREVIEW_MAXIMUM_WIDTH = 512;
export const WORLD_PLAYER_SAVE_PREVIEW_MAXIMUM_HEIGHT = 512;
const MAX_SERIALIZED_SESSION_SAVE_BYTES = 64 * 1024 * 1024;
const idPattern = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/u;
const hashPattern = /^[0-9a-f]{64}$/u;
const slotV1Keys = ["buildId", "format", "kind", "presentationKind", "previewImage", "projectId", "runtimeStateHash", "savedAtEpochMilliseconds", "sceneId", "schemaVersion", "serializedSessionSave", "sessionArtifactHash", "slotId", "title"] as const;
const slotV2Keys = ["buildId", "chapterId", "chapterTitle", "customMetadata", "format", "kind", "migratedFromSchemaVersion", "presentationKind", "preview", "projectId", "route", "runtimeStateHash", "savedAtEpochMilliseconds", "sceneId", "sceneTitle", "schemaVersion", "serializedSessionSave", "sessionArtifactHash", "slotId", "title"] as const;
const slotV3Keys = ["buildId", "chapterId", "chapterTitle", "checkpointStepId", "customMetadata", "format", "kind", "migratedFromSchemaVersion", "presentationKind", "preview", "projectId", "route", "runtimeStateHash", "savedAtEpochMilliseconds", "sceneId", "sceneTitle", "schemaVersion", "serializedSessionSave", "sessionArtifactHash", "slotId", "title"] as const;

export interface WorldPlayerSaveSlotSourceV1 {
  readonly slotId: string;
  readonly projectId: string;
  readonly buildId: string;
  readonly savedAtEpochMilliseconds: number;
  readonly title: string;
  readonly sceneId: string;
  readonly presentationKind: string;
  readonly runtimeStateHash: string;
  readonly sessionArtifactHash: string;
  readonly serializedSessionSave: string;
}

export interface WorldPlayerSaveSlotV1 extends WorldPlayerSaveSlotSourceV1 {
  readonly schemaVersion: 1;
  readonly format: "world.player-save-slot";
  readonly kind: "manual";
  readonly previewImage: null;
}

export type WorldPlayerSavePreviewV2 =
  | { readonly status: "available"; readonly mimeType: "image/webp" | "image/png"; readonly width: number; readonly height: number; readonly byteLength: number; readonly sha256: string }
  | { readonly status: "unavailable"; readonly reason: "capture-unavailable" | "capture-failed" | "capture-invalid" | "legacy-v1" };

export type WorldPlayerSaveKindV2 = "manual" | "auto" | "quick";

export interface WorldPlayerSaveSlotSourceV2 extends WorldPlayerSaveSlotSourceV1 {
