.player-shell[data-player-skin="1"] [data-skin-screen="ending"] { width: min(var(--screen-width), calc(100% - 32px)); max-width: calc(100% - 32px); max-height: min(calc(100dvh - var(--player-viewport-offset, 0px) - 80px), calc((100vw - 40px) / var(--gal-stage-ratio, 1.7778) - 32px), calc(1180px / var(--gal-stage-ratio, 1.7778) - 32px)); overflow-y: auto; }
