.player-shell[data-player-skin="1"] [data-skin-screen] :is(.player-additional-content__grid section, .player-history-list li > button, .player-history-list li > div) { color: var(--skin-text); border-color: var(--skin-border); background: color-mix(in srgb, var(--player-panel) 88%, var(--player-accent) 12%); }
.player-shell[data-player-skin="1"] [data-skin-screen] .player-primary { color: var(--skin-button-text); background: var(--player-accent); }
.player-shell[data-player-skin="1"] [data-skin-screen="save"] .player-save-grid { grid-template-columns: repeat(var(--screen-save-columns), minmax(0, 1fr)); }
.player-shell[data-player-skin="1"] [data-skin-screen="ending"] h2 { font-family: var(--skin-font-title); overflow-wrap: anywhere; }
.player-shell[data-player-skin="1"] [data-skin-screen="ending"] .player-ending-actions { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.player-shell[data-player-skin="1"] [data-skin-screen="ending"] .player-ending-actions > :is(.player-primary, :last-child) { grid-column: 1 / -1; }
.player-shell[data-player-skin="1"] [data-skin-screen][data-skin-motion="fade"] { animation: skin-fade var(--skin-motion-duration) ease-out both; }
.player-shell[data-player-skin="1"] [data-skin-screen][data-skin-motion="rise"] { animation: skin-rise var(--skin-motion-duration) ease-out both; }
