.player-shell[data-player-skin="1"][data-settings-high-contrast="true"] [data-skin-screen] :is(button, select, input, header) { background: #000; border-color: #fff; }
.player-shell[data-player-skin="1"][data-settings-reduce-motion="true"] [data-skin-screen] { animation: none; }
@media (prefers-reduced-motion: reduce) { .player-shell[data-player-skin="1"] [data-skin-screen] { animation: none; } }
@media (max-width: 640px) {
  .player-shell[data-player-skin="1"] [data-skin-screen="ending"] .player-ending-actions { grid-template-columns: minmax(0, 1fr); }
  .player-shell[data-player-skin="1"] [data-skin-screen]:not([data-skin-screen="ending"]) { inset-inline: max(12px, env(safe-area-inset-left)) max(12px, env(safe-area-inset-right)); width: calc(100vw - max(12px, env(safe-area-inset-left)) - max(12px, env(safe-area-inset-right))); max-width: calc(100vw - max(12px, env(safe-area-inset-left)) - max(12px, env(safe-area-inset-right))); margin-inline: 0; padding: min(var(--screen-padding), 22px); }
  .player-shell[data-player-skin="1"] [data-skin-screen="save"] .player-save-grid { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 640px) and (orientation: portrait) { .player-shell[data-player-skin="1"] [data-skin-screen="ending"] { max-height: calc(100dvh - var(--player-viewport-offset, 0px) - 80px); } }

import type { CSSProperties } from "react";
import type { WebPlayerScreenId, WebPlayerSkin } from "@world-studio/project-domain";
import { defaultWebPlayerScreens } from "@world-studio/project-domain";

export function playerScreenProps(skin: WebPlayerSkin | undefined, screen: WebPlayerScreenId) {
  if (!skin || !skin.screens && !skin.images) return {};
  const screens = skin.screens ?? defaultWebPlayerScreens(), panel = screens.panels[screen], color = skin.colors.panel;
  return {
    "data-skin-screen": screen,
    "data-skin-placement": panel.placement,
    "data-skin-motion": panel.motion,
    style: {
      "--screen-width": `${panel.width}px`, "--screen-radius": `${panel.radius}px`, "--screen-padding": `${panel.padding}px`, "--screen-font-size": `${panel.fontSize}px`,
      "--screen-background": `rgba(${parseInt(color.slice(1, 3), 16)},${parseInt(color.slice(3, 5), 16)},${parseInt(color.slice(5, 7), 16)},${panel.opacity / 100})`,
      "--screen-save-columns": screens.saveColumns,
      "--screen-image": `var(--skin-${screen}-background, none)`, "--screen-image-fit": `var(--skin-${screen}-background-fit, cover)`
    } as CSSProperties
  };
}

