:root {
  color: #f8f7ff;
  background: #090b18;
  font-family: Inter, "Segoe UI", "Microsoft YaHei UI", sans-serif;
  font-synthesis: none;
}

/* Optional project-owned appearance; legacy projects retain their existing look. */
.player-shell[data-player-theme] { --player-accent: #b9a1ff; --player-ink: #f8f7ff; --player-muted: #c1bed2; --player-panel: #111425; }
.player-shell[data-player-accent="teal"] { --player-accent: #6edbc4; }
.player-shell[data-player-accent="rose"] { --player-accent: #ff9eb6; }
.player-shell[data-player-theme="paper"] { --player-ink: #302b31; --player-muted: #625965; --player-panel: #fff8ed; color: var(--player-ink); background: #eee3d3; }
.player-shell[data-player-theme="paper"] .player-stage { background: #eee3d3; border-color: #cbbfb2; }
.player-shell[data-player-theme] .player-title-screen { isolation: isolate; padding: clamp(18px, 4vw, 36px); border-radius: 24px; background: var(--player-panel); color: var(--player-ink); overflow: hidden; }
.player-shell[data-player-theme] .player-title-screen > :not(.player-title-cover) { position: relative; z-index: 1; }
.player-shell[data-player-theme] .player-title-cover { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: .22; z-index: -1; }
.player-shell[data-player-theme] .player-title-screen > p:not(.player-eyebrow) { color: var(--player-muted); white-space: pre-line; }
.player-shell[data-player-theme] .player-primary { background: var(--player-accent); color: #201627; }
.player-shell[data-player-theme] .player-choice button { border-color: var(--player-accent); }
.player-shell[data-player-theme="paper"] :is(.player-save__panel, .player-history-panel, .player-recovery, .player-playback-controls, .player-history-controls) { background: var(--player-panel); color: var(--player-ink); border-color: #bcb1a5; }
.player-shell[data-player-theme="paper"] :is(.player-save__panel, .player-history-panel, .player-recovery) :is(button, span, small, p) { color: var(--player-ink); }
.player-shell[data-player-theme="paper"] :is(.player-save button, .player-history-controls button, .player-playback-controls button, .player-playback-controls select, .player-title-recovery button) { background: var(--player-panel); color: var(--player-ink); border-color: #bcb1a5; }
.player-shell[data-player-theme="paper"] .player-dialogue { background: rgba(255,248,237,var(--gal-message-opacity,.88)); color: #302b31; border-color: #bcb1a5; }
.player-shell[data-player-theme="paper"] .player-dialogue :is(p, .player-narration) { color: #302b31; }
.player-shell[data-player-theme="paper"] .player-dialogue__speaker { color: #6b3659; }
.player-shell[data-player-theme="paper"] .player-dialogue i { color: #625965; }
.player-shell[data-player-theme="paper"] .player-playback-controls label { color: var(--player-muted); }
.player-shell[data-player-theme="paper"] .player-title-screen .player-eyebrow { color: #6b3659; }
.player-shell[data-player-theme="paper"] .player-history-controls__position { color: var(--player-muted); }
.player-shell[data-player-theme="paper"] .player-choice button { background: #fff8ed; color: #302b31; }
.player-shell[data-player-theme="paper"] .player-choice button > [data-choice-number] { color: #6b3659; background: #f3d8e4; }
.player-shell[data-player-theme="paper"] :is(.player-ending, .player-error, .player-hint, .player-title-recovery, .player-recovery span) { color: var(--player-ink); }
.player-shell[data-player-theme] :is(.player-save__views button[aria-pressed="true"], .player-history-controls__open, .player-playback-controls button[aria-pressed="true"]) { border-color: var(--player-accent); }
.player-shell[data-player-theme][data-settings-high-contrast="true"] :is(.player-title-screen, .player-save__panel, .player-history-panel, .player-recovery, .player-playback-controls, .player-history-controls) { background: #000; color: #fff; border-color: #fff; }
.player-shell[data-player-theme][data-settings-high-contrast="true"] :is(.player-title-screen p, .player-save__panel span, .player-recovery span, .player-playback-controls label) { color: #fff; }
