* { box-sizing: border-box; }
html, body, #root { min-width: 320px; min-height: 100%; margin: 0; }
button { font: inherit; }
.player-control-layer { display: contents; }
.player-compact-toolbar { display: none; }
#player-root[data-startup-state]:not([data-startup-state="ready"]) {
  box-sizing: border-box; min-height: 100vh; padding: 32px;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 16px; text-align: center;
}
#player-root[data-startup-state]:not([data-startup-state="ready"]) > button {
  min-height: 44px; padding: 10px 24px; border: 1px solid #67e8f9;
  border-radius: 12px; background: #164e63; color: #ecfeff; cursor: pointer;
}
#player-root[data-startup-state]:not([data-startup-state="ready"]) > button:focus-visible {
  outline: 3px solid #fef08a; outline-offset: 4px;
}
.player-demo-switch { position: fixed; z-index: 20; top: max(12px, env(safe-area-inset-top)); right: max(12px, env(safe-area-inset-right)); min-height: 44px; padding: 0 14px; border: 1px solid rgba(103,232,249,.35); border-radius: 12px; color: #cffafe; background: rgba(8,10,25,.82); cursor: pointer; backdrop-filter: blur(18px); }
.player-demo-controls { position: fixed; z-index: 30; top: max(12px, env(safe-area-inset-top)); right: max(12px, env(safe-area-inset-right)); display: flex; gap: 8px; }
.player-demo-controls button { min-height: 44px; padding: 0 14px; border: 1px solid rgba(103,232,249,.35); border-radius: 12px; color: #cffafe; background: rgba(8,10,25,.88); cursor: pointer; backdrop-filter: blur(18px); }

.player-shell {
  position: relative;
  display: grid;
  min-height: calc(100dvh - var(--player-viewport-offset, 0px));
  place-items: center;
  overflow: hidden;
  padding: max(20px, env(safe-area-inset-top)) max(20px, env(safe-area-inset-right)) max(20px, env(safe-area-inset-bottom)) max(20px, env(safe-area-inset-left));
  background:
    radial-gradient(circle at 50% 0%, #272154 0, transparent 45%),
    linear-gradient(145deg, #090b18 0%, #11142b 55%, #08151c 100%);
}
.player-shell[data-settings-safe-area="none"] { padding: 20px; }

.player-glow { position: absolute; width: 38vw; aspect-ratio: 1; border-radius: 50%; filter: blur(80px); opacity: .22; pointer-events: none; }
.player-glow--violet { top: -18%; left: -8%; background: #a855f7; }
.player-glow--cyan { right: -10%; bottom: -25%; background: #22d3ee; }

.player-stage {
  position: relative;
  display: grid;
  width: min(1180px, 100%, calc((100dvh - 40px - var(--player-viewport-offset, 0px)) * var(--gal-stage-ratio, 1.7778)));
  aspect-ratio: var(--gal-stage-aspect, 16 / 9);
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: clamp(22px, 3vw, 38px);
  background:
    linear-gradient(180deg, rgba(16,19,43,.32), rgba(7,9,21,.84)),
    radial-gradient(circle at 72% 25%, rgba(56,189,248,.2), transparent 33%),
    linear-gradient(125deg, #282255, #151b3c 52%, #102b34);
  box-shadow: 0 30px 100px rgba(0,0,0,.48), inset 0 1px rgba(255,255,255,.1);
}

.player-stage::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,.025) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.025) 1px, transparent 1px);
  background-size: 42px 42px;
  mask-image: linear-gradient(to bottom, black, transparent 70%);
  pointer-events: none;
}

.player-stage-world { position: absolute; inset: 0; overflow: hidden; transform-origin: center; transition: transform .6s cubic-bezier(.2,.8,.2,1); }
.player-stage-background { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; image-rendering: auto; }
.player-shell[data-settings-quality="low"] .player-stage-background,
.player-shell[data-settings-quality="low"] .player-stage-character { image-rendering: optimizeSpeed; }
.player-stage-character { position: absolute; width: clamp(120px, 30%, 390px); max-height: 92%; object-fit: contain; transform-origin: bottom center; filter: drop-shadow(0 24px 34px rgba(0,0,0,.42)); }
.player-transition--fade { animation: player-media-fade .55s ease both; }
.player-transition--dissolve { animation: player-media-dissolve .65s ease both; }
.player-transition--slide { animation: player-media-slide .55s cubic-bezier(.2,.8,.2,1) both; }
.player-scene-description { position: absolute; inset: 0; display: grid; place-items: center; padding: 14%; color: rgba(255,255,255,.48); font-size: clamp(15px, 2vw, 22px); line-height: 1.75; text-align: center; background: radial-gradient(circle at 50% 66%, rgba(34,211,238,.16), transparent 32%), linear-gradient(155deg, rgba(93,49,140,.2), rgba(4,17,31,.62)); }

.player-brand { position: absolute; z-index: 2; top: 24px; left: 28px; display: flex; align-items: center; gap: 10px; color: rgba(255,255,255,.7); font-size: 13px; font-weight: 700; letter-spacing: .08em; }
.player-brand__mark { display: grid; width: 30px; height: 30px; place-items: center; border-radius: 10px; color: white; background: linear-gradient(135deg, #a855f7, #06b6d4); box-shadow: 0 8px 24px rgba(168,85,247,.35); }
.player-brand__status { padding: 5px 9px; border: 1px solid rgba(255,255,255,.12); border-radius: 999px; color: #a5f3fc; font-size: 10px; text-transform: uppercase; }
.player-brand__effect { padding: 5px 9px; border-radius: 999px; color: #ddd6fe; background: rgba(139,92,246,.14); font-size: 10px; letter-spacing: .04em; }
.player-replay-status { position: absolute; z-index: 7; top: 82px; left: 24px; display: flex; width: min(440px, calc(100% - 48px)); align-items: center; gap: 14px; padding: 11px 12px 11px 15px; border: 1px solid rgba(251,191,36,.42); border-radius: 15px; color: #fff; background: rgba(31,22,11,.9); box-shadow: 0 16px 42px rgba(0,0,0,.32); backdrop-filter: blur(18px); }
.player-replay-status > div { display: grid; min-width: 0; flex: 1; gap: 2px; }
