.player-shell[data-player-skin="1"] .player-primary { color: var(--skin-button-text); border-radius: var(--skin-button-radius); }
.player-shell[data-player-skin="1"] .player-title-actions { justify-content: inherit; }
.player-shell[data-player-skin="1"] .player-dialogue { left: max(12px, calc((100% - var(--skin-window-width)) / 2)); right: max(12px, calc((100% - var(--skin-window-width)) / 2)); border-radius: var(--skin-window-radius); padding: var(--skin-window-padding); border-color: var(--skin-border); color: var(--skin-text); background: var(--skin-window); background-image: var(--skin-window-image); background-size: 100% 100%; }
